const replace = require("./slugify");

describe("replace", () => {
  it("throws for non-string input", () => {
    expect(() => replace(123)).toThrow('slugify: string argument expected')
    expect(() => replace(null)).toThrow('slugify: string argument expected')
  });

  it("slugifies basic ASCII text with default options", () => {
    expect(replace('Hello World')).toBe('Hello-World')
    expect(replace('multiple   spaces')).toBe('multiple-spaces')
  });

  it("uses string replacement argument and lowercasing", () => {
    expect(replace('Hello World', '_')).toBe('Hello_World')
    expect(replace('Hello World', { replacement: '_', lower: true })).toBe('hello_world')
  });

  it("applies locale-specific replacements", () => {
    expect(replace('äöüß', { locale: 'de' })).toBe('aeoeuess')
    expect(replace('&|♥', { locale: 'fr' })).toBe('etouamour')
  });

  it("respects strict, trim, and custom remove options", () => {
    expect(replace('  Café!  ', { strict: true })).toBe('Cafe')
    expect(replace('a,b.c', { remove: /[,]/g })).toBe('ab.c')
    expect(replace('  hi  ', { trim: false })).toBe('-hi-')
  });
});
